    pub fn has_live_sensing_monitors(&self) -> bool { false }
    pub fn set_target_fence_geometry(&mut self, target: usize, geometry: SpriteFenceGeometry) { self.state.set_target_fence_geometry(target, geometry); }
    pub fn begin_tick(&mut self) { self.state.begin_tick(); }
    pub fn redraw_requested(&self) -> bool { self.state.redraw_requested() }
    pub fn presentation_requested(&self) -> bool { self.state.presentation_requested() }
    pub fn presentation_consumed(&mut self) { self.state.presentation_consumed(); }
    pub fn apply_input(&mut self, event: RuntimeInputEvent) { if let Some(key) = self.state.apply_input(event) { let scripts = new_keypress_scripts(&key, &self.state); self.scheduler.start_key_hats(scripts); } }
    pub fn set_loudness(&mut self, value: f64) { self.state.set_loudness(value); }
    pub fn observable_snapshot(&mut self, tick: usize) -> RuntimeSnapshot { self.snapshot(tick, true) }
    pub fn renderer_snapshot(&mut self, tick: usize) -> RuntimeSnapshot { self.snapshot(tick, false) }
    fn snapshot(&mut self, tick: usize, include_hidden_items: bool) -> RuntimeSnapshot { let mut snapshot = self.state.observable_snapshot_filtered(tick, include_hidden_items);
        snapshot.reporters = Vec::with_capacity(2);
        { let state = &self.state; let _ = state; let value: ScratchValue = (self.state.mouse_x()).into(); snapshot.reporters.push(ReporterSnapshot { key: "__reporter/Stage/sensing_mousex/sensing_mousex".to_owned(), value }); }
        { let state = &self.state; let _ = state; let value: ScratchValue = (self.state.mouse_y()).into(); snapshot.reporters.push(ReporterSnapshot { key: "__reporter/Stage/sensing_mousey/sensing_mousey".to_owned(), value }); }
        snapshot }
    pub fn take_pending_pen_commands(&mut self) -> Vec<PenCommand> { self.state.take_pending_pen_commands() }
    pub fn set_observable_event_sink(&mut self, sink: Option<std::sync::mpsc::Sender<ObservableEvent>>) { self.state.set_event_sink(sink); }
    pub fn run_until_complete(&mut self) { loop { match self.advance_frame() { SchedulerStatus::Progressed => {}, SchedulerStatus::WaitingUntil(deadline) => std::thread::sleep(self.duration_until(deadline)), SchedulerStatus::WaitingForSignal => std::thread::sleep(std::time::Duration::from_millis(8)), SchedulerStatus::Complete => break } } }
